UPDATE public.weapons w
SET
  max_name = n.max_name,
  rarity_names = n.rarity_names
FROM _weapon_name_import n
WHERE w.id = n.id;

-- 3. Populate weapon_upgrades.name
CREATE TEMP TABLE _weapon_upgrade_name_import (
  weapon_id TEXT,
  rarity INTEGER,
  name TEXT,
  PRIMARY KEY (weapon_id, rarity)
) ON COMMIT DROP;

